function criarSaudacao(nome, saudacao = "Olá") {
  return `${saudacao}, ${nome}!`;
}

console.log(criarSaudacao("Marta")); // "Olá, Marta!"
console.log(criarSaudacao("Marta", "Bom dia")); // "Bom dia, Marta!"

function calcularMedia(...notas) {
  if (notas.length === 0) return 0;

  let soma = 0;
  for (const nota of notas) {
    soma += nota;
  }

  return Number((soma / notas.length).toFixed(2));
}

console.log(calcularMedia(14, 16, 12)); // 14
console.log(calcularMedia(18, 15)); // 16.5
console.log(calcularMedia()); // 0

exercises.statement:
Tem a seguinte função tradicional:

function somarTudo() {
  let total = 0;
  for (let i = 0; i < arguments.length; i++) {
    total += arguments[i];
  }
  return total;
}

Reescreva-a como uma arrow function com o mesmo nome (somarTudo) e o mesmo comportamento, mas usando rest parameters em vez do objeto arguments. Depois, num comentário no código, explique porque é que não seria possível manter o uso de arguments dentro dessa arrow function.

exercises.solution_code:
const somarTudo = (...numeros) => {
  let total = 0;
  for (const numero of numeros) {
    total += numero;
  }
  return total;
};

console.log(somarTudo(1, 2, 3)); // 6

// Porque não dava para usar "arguments" dentro desta arrow function:
// arrow functions não criam o seu próprio arguments; se tentássemos usá-lo aqui,
// o motor iria procurar o arguments da função tradicional mais próxima que a
// envolvesse (ou lançaria ReferenceError, caso a arrow estivesse no topo do
// ficheiro, fora de qualquer função). Por isso, rest parameters são a única
// forma correta de aceitar um número variável de argumentos numa arrow function.

function criarFatura(cliente, taxaIva = 0.23, ...itens) {
  let subtotal = 0;
  for (const item of itens) {
    subtotal += item.preco;
  }

  const totalComIva = subtotal * (1 + taxaIva);

  return {
    cliente,
    subtotal,
    totalComIva: Number(totalComIva.toFixed(2)),
    itens
  };
}

const itensLoja1 = [
  { nome: "Teclado", preco: 45 },
  { nome: "Rato", preco: 20 }
];
const itensLoja2 = [{ nome: "Monitor", preco: 150 }];

// undefined mantém o valor por omissão de taxaIva (0.23) enquanto se chega ao rest
const fatura = criarFatura("Cliente Final", undefined, ...itensLoja1, ...itensLoja2);

console.log(fatura);
// { cliente: "Cliente Final", subtotal: 215, totalComIva: 264.45, itens: [...] }
